#!/usr/bin/env node

import { pathToFileURL } from 'node:url';

import {
  b58decode,
  b58decodeCheck,
  b58decodeInt,
  b58encode,
  b58encodeCheck,
  b58encodeInt,
  CliParseError,
  formatPythonBytes,
  formatPythonInt,
  getProgramName,
  HelpRequested,
  parseArgs,
  renderParseError,
  utf8Encode,
} from './lib/index.mjs';

export function main(argv = process.argv.slice(2)) {
  const programName = getProgramName();

  try {
    const args = parseArgs(argv, programName);

    const encodedA = b58encode(utf8Encode(args.a));
    const decodedB = b58decode(args.b);
    const encodedCheckC = b58encodeCheck(utf8Encode(args.c));
    const decodedCheckC = b58decodeCheck(encodedCheckC);
    const encodedD = b58encode(utf8Encode(args.d));
    const decodedD = b58decode(encodedD);
    const encodedIntE = b58encodeInt(args.e);
    const encodedIntF = b58encodeInt(args.f);
    const decodedIntE = b58decodeInt(encodedIntE);
    const encodedCheckDecoded = b58encodeCheck(decodedB);

    const outputLines = [
      formatPythonBytes(encodedA),
      formatPythonBytes(decodedB),
      formatPythonBytes(encodedCheckC),
      formatPythonBytes(decodedCheckC),
      formatPythonBytes(encodedD),
      formatPythonBytes(decodedD),
      formatPythonBytes(encodedIntE),
      formatPythonBytes(encodedIntF),
      formatPythonInt(decodedIntE),
      formatPythonBytes(encodedCheckDecoded),
    ];

    process.stdout.write(`${outputLines.join('\n')}\n`);
    return 0;
  } catch (error) {
    if (error instanceof HelpRequested) {
      process.stdout.write(error.helpText);
      return 0;
    }

    if (error instanceof CliParseError) {
      process.stderr.write(renderParseError(error.message, programName));
      return 2;
    }

    throw error;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const exitCode = main();
  if (exitCode !== 0) {
    process.exitCode = exitCode;
  }
}

