import { basename } from 'node:path';

const OPTION_SPECS = [
  { name: 'a', option: '--a', metavar: 'A', type: 'string' },
  { name: 'b', option: '--b', metavar: 'B', type: 'string' },
  { name: 'c', option: '--c', metavar: 'C', type: 'string' },
  { name: 'd', option: '--d', metavar: 'D', type: 'string' },
  { name: 'e', option: '--e', metavar: 'E', type: 'int' },
  { name: 'f', option: '--f', metavar: 'F', type: 'int' },
];

const SPEC_BY_OPTION = new Map(OPTION_SPECS.map((spec) => [spec.option, spec]));

function quoted(value) {
  return `'${value}'`;
}

function isNegativeIntegerToken(token) {
  return /^-[0-9](?:_?[0-9])*$/u.test(token);
}

function expectsValue(token) {
  if (token === undefined) {
    return false;
  }

  if (token === '-') {
    return true;
  }

  if (!token.startsWith('-')) {
    return true;
  }

  return isNegativeIntegerToken(token);
}

function parseIntValue(rawValue, option) {
  const normalized = rawValue.trim();

  if (!/^[+-]?(?:[0-9](?:_?[0-9])*)$/u.test(normalized)) {
    throw new CliParseError(`argument ${option}: invalid int value: ${quoted(rawValue)}`);
  }

  return BigInt(normalized.replace(/_/gu, ''));
}

export class CliParseError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CliParseError';
  }
}

export class HelpRequested extends Error {
  constructor(helpText) {
    super('');
    this.name = 'HelpRequested';
    this.helpText = helpText;
  }
}

export function getProgramName(scriptPath = process.argv[1]) {
  return basename(scriptPath || 'test19.mjs');
}

export function renderUsage(programName = getProgramName()) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D --e E --f F`;
}

export function renderHelp(programName = getProgramName()) {
  const optionLines = OPTION_SPECS.map(
    (spec) => `  ${spec.option} ${spec.metavar}`,
  ).join('\n');

  return `${renderUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n${optionLines}\n`;
}

export function renderParseError(errorMessage, programName = getProgramName()) {
  return `${renderUsage(programName)}\n${programName}: error: ${errorMessage}\n`;
}

export function parseArgs(argv, programName = getProgramName()) {
  const parsed = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      throw new HelpRequested(renderHelp(programName));
    }

    if (token === '--') {
      extras.push(...argv.slice(index));
      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const option = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const spec = SPEC_BY_OPTION.get(option);

      if (!spec) {
        extras.push(token);

        if (equalsIndex === -1 && index + 1 < argv.length && expectsValue(argv[index + 1])) {
          extras.push(argv[index + 1]);
          index += 1;
        }

        continue;
      }

      let rawValue;

      if (equalsIndex !== -1) {
        rawValue = token.slice(equalsIndex + 1);
      } else {
        const candidate = argv[index + 1];

        if (!expectsValue(candidate)) {
          throw new CliParseError(`argument ${option}: expected one argument`);
        }

        rawValue = candidate;
        index += 1;
      }

      parsed[spec.name] = spec.type === 'int'
        ? parseIntValue(rawValue, option)
        : rawValue;
      continue;
    }

    extras.push(token);
  }

  if (extras.length > 0) {
    throw new CliParseError(`unrecognized arguments: ${extras.join(' ')}`);
  }

  const missing = OPTION_SPECS
    .filter((spec) => !(spec.name in parsed))
