export function utf8Encode(value) {
  const encoded = encodeURIComponent(value);
  const bytes = [];

  for (let index = 0; index < encoded.length; index += 1) {
    const char = encoded[index];

    if (char === '%') {
      bytes.push(Number.parseInt(encoded.slice(index + 1, index + 3), 16));
      index += 2;
