import { doubleSha256Bytes } from './checksum.mjs';

const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const ZERO_SYMBOL = ALPHABET[0];
const BASE = 58n;
const ALPHABET_INDEX = new Map(
  Array.from(ALPHABET, (character, index) => [character, index]),
);

function divmodFloor(value, divisor) {
  let quotient = value / divisor;
  let remainder = value % divisor;

  if (remainder < 0n) {
    quotient -= 1n;
    remainder += divisor;
  }

  return [quotient, remainder];
}

function checksumBytes(payload) {
  return doubleSha256Bytes(payload).slice(0, 4);
}

export function b58encodeIntText(value, defaultOne = true) {
  if (value === 0n) {
    return defaultOne ? ZERO_SYMBOL : '';
  }

  let remaining = value;
  let encoded = '';

  while (remaining !== 0n) {
    const [quotient, remainder] = divmodFloor(remaining, BASE);
    encoded = ALPHABET[Number(remainder)] + encoded;
    remaining = quotient;
  }

  return encoded;
}

export function b58encodeInt(value, defaultOne = true) {
  return asciiTextToBytes(b58encodeIntText(value, defaultOne));
}

export function b58decodeInt(value) {
  const text = rstripWhitespace(normalizeBase58Input(value));
  let decoded = 0n;

  for (const character of text) {
    const digit = ALPHABET_INDEX.get(character);

    if (digit === undefined) {
      throw new Error(`Invalid character '${character}'`);
    }

    decoded = (decoded * BASE) + BigInt(digit);
  }

  return decoded;
}

export function b58encodeText(bytes) {
  if (bytes.length === 0) {
    return '';
  }

  let leadingZeroCount = 0;

  while (leadingZeroCount < bytes.length && bytes[leadingZeroCount] === 0) {
    leadingZeroCount += 1;
  }

  const payload = bytes.slice(leadingZeroCount);
  const encodedPayload = b58encodeIntText(bytesToBigInt(payload), false);

  return ZERO_SYMBOL.repeat(leadingZeroCount) + encodedPayload;
}

export function b58encode(bytes) {
  return asciiTextToBytes(b58encodeText(bytes));
}

export function b58decode(value) {
  const text = rstripWhitespace(normalizeBase58Input(value));

  if (text.length === 0) {
    return [];
  }

  let leadingZeroCount = 0;

  while (leadingZeroCount < text.length && text[leadingZeroCount] === ZERO_SYMBOL) {
    leadingZeroCount += 1;
  }

  const decodedPayload = bigIntToBytes(b58decodeInt(text));
  return new Array(leadingZeroCount).fill(0).concat(decodedPayload);
}

export function b58encodeCheckText(bytes) {
  return b58encodeText(bytes.concat(checksumBytes(bytes)));
}

export function b58encodeCheck(bytes) {
  return asciiTextToBytes(b58encodeCheckText(bytes));
}

export function b58decodeCheck(value) {
  const decoded = b58decode(value);

  if (decoded.length < 4) {
    throw new Error('Invalid checksum');
  }

