import { createHash } from 'node:crypto';

import { bytesToLatin1, latin1ToBytes } from './bytes.mjs';

export function sha256Bytes(bytes) {
  const hash = createHash('sha256');
  hash.update(bytesToLatin1(bytes), 'latin1');
  return latin1ToBytes(hash.digest('latin1'));
}

export function doubleSha256Bytes(bytes) {
  return sha256Bytes(sha256Bytes(bytes));
}

